import{I as e,L as t,O as n,j as r,k as i,t as a}from"./app-DO0QAytN.js";var o=JSON.parse(`{"path":"/interview/rag-interview/chunk-strategy.html","title":"文档切分为什么重要？","lang":"zh-CN","frontmatter":{"title":"文档切分为什么重要？","icon":"mdi:scissors-cutting","tag":["RAG面试","文档切分","Chunk策略"],"description":"文档切分为什么重要？chunk size 和 overlap 应该怎么选？ 这道题考察的是你对RAG系统&quot;地基&quot;的理解。文档切分看似简单，却是决定召回质量的关键环节。下面我们逐个拆解。 板块1：文档切分决定了RAG的召回上限 RAG的流程大家都熟悉：文档→切分→向量化→检索→生成。 但很多人没意识到，&quot;切分&quot;这一...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"文档切分为什么重要？\\",\\"image\\":[\\"https://www.anyiai.cc/images/rag-interview/chunk-strategy_cover.png\\",\\"https://www.anyiai.cc/images/rag-interview/20260608_195643_665664_01.png\\",\\"https://www.anyiai.cc/images/rag-interview/20260608_195638_666560_01.png\\",\\"https://www.anyiai.cc/images/rag-interview/20260608_195645_105792_01.png\\",\\"https://www.anyiai.cc/images/rag-interview/20260608_195658_159872_01.png\\",\\"https://www.anyiai.cc/images/rag-interview/20260608_195701_910272_01.png\\"],\\"dateModified\\":\\"2026-10-28T04:17:51.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"安逸Ai\\"}]}"],["meta",{"property":"og:url","content":"https://www.anyiai.cc/interview/rag-interview/chunk-strategy.html"}],["meta",{"property":"og:site_name","content":"AI 学习资源站"}],["meta",{"property":"og:title","content":"文档切分为什么重要？"}],["meta",{"property":"og:description","content":"文档切分为什么重要？chunk size 和 overlap 应该怎么选？ 这道题考察的是你对RAG系统&quot;地基&quot;的理解。文档切分看似简单，却是决定召回质量的关键环节。下面我们逐个拆解。 板块1：文档切分决定了RAG的召回上限 RAG的流程大家都熟悉：文档→切分→向量化→检索→生成。 但很多人没意识到，&quot;切分&quot;这一..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://www.anyiai.cc/images/rag-interview/chunk-strategy_cover.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-28T04:17:51.000Z"}],["meta",{"property":"article:tag","content":"Chunk策略"}],["meta",{"property":"article:tag","content":"文档切分"}],["meta",{"property":"article:tag","content":"RAG面试"}],["meta",{"property":"article:modified_time","content":"2026-10-28T04:17:51.000Z"}],["link",{"rel":"canonical","href":"https://www.anyiai.cc/interview/rag-interview/chunk-strategy.html"}]]},"git":{"createdTime":1793161071000,"updatedTime":1793161071000,"contributors":[{"name":"anyi","username":"anyi","email":"1961741003@qq.com","commits":1,"url":"https://github.com/anyi"}]},"readingTime":{"minutes":6.58,"words":1974},"filePathRelative":"interview/rag-interview/chunk-strategy.md","autoDesc":true}`),s={name:`chunk-strategy.md`};function c(a,o,s,c,l,u){let d=t(`ReadMoreLock`);return e(),n(`div`,null,[o[0]||=i(`<figure><img src="/images/rag-interview/chunk-strategy_cover.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h1 id="文档切分为什么重要-chunk-size-和-overlap-应该怎么选" tabindex="-1"><a class="header-anchor" href="#文档切分为什么重要-chunk-size-和-overlap-应该怎么选"><span>文档切分为什么重要？chunk size 和 overlap 应该怎么选？</span></a></h1><p>这道题考察的是你对RAG系统&quot;地基&quot;的理解。文档切分看似简单，却是决定召回质量的关键环节。下面我们逐个拆解。</p><hr><h2 id="板块1-文档切分决定了rag的召回上限" tabindex="-1"><a class="header-anchor" href="#板块1-文档切分决定了rag的召回上限"><span>板块1：文档切分决定了RAG的召回上限</span></a></h2><p>RAG的流程大家都熟悉：<strong>文档→切分→向量化→检索→生成</strong>。</p><p>但很多人没意识到，&quot;切分&quot;这一步直接框死了召回的天花板。Embedding模型再强、LLM再聪明，如果chunk本身切得乱七八糟，检索阶段就不可能召回正确的内容。</p><p>类比一下：Chunk就像盖房子的地基。你可以在上面设计漂亮的屋顶、精致的装修，但地基没打好，整个房子都站不住。</p><p>具体来说，chunk的大小、边界、完整性，会直接影响：</p><ul><li>检索时能不能命中用户问题的相关上下文</li><li>召回的内容是否包含完整的语义信息</li><li>生成阶段LLM拿到的是有效信息还是碎片噪音</li></ul><p><strong>所以数据处理管线做到位，比换一百个embedding模型都管用。</strong></p><figure><img src="/images/rag-interview/20260608_195643_665664_01.png" alt="RAG流水线图，展示文档→切分→向量化→检索→生成的完整流程，标注chunking是核心环节" tabindex="0" loading="lazy"><figcaption>RAG流水线图，展示文档→切分→向量化→检索→生成的完整流程，标注chunking是核心环节</figcaption></figure><hr>`,13),r(d),o[1]||=i(`<h2 id="板块2-chunk-size的选择是精度和完整性的博弈" tabindex="-1"><a class="header-anchor" href="#板块2-chunk-size的选择是精度和完整性的博弈"><span>板块2：chunk size的选择是精度和完整性的博弈</span></a></h2><p>选chunk size，本质上是在两件事之间找平衡：<strong>语义完整度</strong> 和 <strong>embedding精度</strong>。</p><h3 id="chunk太小会有问题" tabindex="-1"><a class="header-anchor" href="#chunk太小会有问题"><span>chunk太小会有问题</span></a></h3><p>想象一个200字的段落，里面讲了&quot;问题背景→解决方案→效果结论&quot;，你非把它切成50字一段。结果呢？每段都只有半个意思，检索时可能召回&quot;背景&quot;但漏掉&quot;解决方案&quot;。</p><p>太小的chunk会导致：</p><ul><li>语义断裂，上下文丢失</li><li>关键信息被拆散，召回不完整</li><li>很多检索其实是在&quot;盲人摸象&quot;</li></ul><h3 id="chunk太大也会有问题" tabindex="-1"><a class="header-anchor" href="#chunk太大也会有问题"><span>chunk太大也会有问题</span></a></h3><p>反过来，如果把整篇文章塞进一个1000 tokens的chunk，embedding模型会把所有信息压缩成一个向量。问题是：<strong>一个向量能代表一篇文章的所有主题吗？</strong> 当然不能。</p><p>太大的chunk会导致：</p><ul><li>语义稀释，多主题内容互相干扰</li><li>embedding失真，&quot;平均&quot;后的向量失去区分度</li><li>检索时召回大量无关内容，增加LLM的处理负担</li></ul><h3 id="那到底怎么选" tabindex="-1"><a class="header-anchor" href="#那到底怎么选"><span>那到底怎么选？</span></a></h3><p>通用场景下，<strong>400-512 tokens</strong>是经验上的&quot;甜点区间&quot;。这个范围既能保证语义的相对完整，又不会让embedding过度稀释。</p><p>但不同场景要有不同策略：</p><ul><li><strong>代码文档</strong>：建议~100 tokens，按函数/方法切</li><li><strong>长篇论述</strong>：建议400-512 tokens，按段落切</li><li><strong>FAQ问答</strong>：保留完整问答对，一刀切都不行</li></ul><p>类比一下：切西瓜。切太大吃不完浪费，切太小吃不过瘾。找到刚好一口能吃掉的大小，才是目标。</p><figure><img src="/images/rag-interview/20260608_195638_666560_01.png" alt="chunk大小对比图，左边显示太小的问题、右边显示太大的问题、中间标注最佳区间400-512" tabindex="0" loading="lazy"><figcaption>chunk大小对比图，左边显示太小的问题、右边显示太大的问题、中间标注最佳区间400-512</figcaption></figure><hr><h2 id="板块3-overlap解决跨chunk的边界丢失问题" tabindex="-1"><a class="header-anchor" href="#板块3-overlap解决跨chunk的边界丢失问题"><span>板块3：overlap解决跨chunk的边界丢失问题</span></a></h2><p>假设有一段话：</p><blockquote><p>&quot;Transformer通过自注意力机制捕捉序列中的依赖关系，其核心是Query、Key、Value三个矩阵的计算。&quot;</p></blockquote><p>如果刚好在&quot;核心是&quot;后面切了一刀，检索&quot;Query矩阵&quot;的用户就可能拿到后半段，而漏掉了前面&quot;Transformer通过自注意力机制&quot;这个关键上下文。</p><p>这种<strong>跨chunk的边界丢失</strong>很常见，尤其是当关键信息跨越两个chunk时。</p><h3 id="overlap的解决方案" tabindex="-1"><a class="header-anchor" href="#overlap的解决方案"><span>Overlap的解决方案</span></a></h3><p>很简单：让相邻的chunk有重叠区域。比如：</p><ul><li>Chunk1： tokens 1-512</li><li>Chunk2： tokens 450-962（重叠62个token）</li></ul><p>这样即使关键信息刚好在边界处，下一个chunk也能捞回一部分上下文。</p><p><strong>推荐的重叠比例是10%-20%</strong>。太高会引入大量冗余信息，检索质量反而下降；太低就起不到保护边界的作用。</p><p>再用一个类比：拼图。每块拼图边缘都有一小部分图案是&quot;重复&quot;的，这样拼的时候才能确保图案连贯不断裂。Overlap就是那个&quot;重复的边缘&quot;。</p><figure><img src="/images/rag-interview/20260608_195645_105792_01.png" alt="重叠示意图，两个相邻chunk有10%-20%重叠区域，重叠部分标注&quot;共享上下文&quot;" tabindex="0" loading="lazy"><figcaption>重叠示意图，两个相邻chunk有10%-20%重叠区域，重叠部分标注&quot;共享上下文&quot;</figcaption></figure><hr><h2 id="板块4-不同场景要用不同切分策略" tabindex="-1"><a class="header-anchor" href="#板块4-不同场景要用不同切分策略"><span>板块4：不同场景要用不同切分策略</span></a></h2><p>前面说的都是通用原则，但实战中<strong>不同文档类型要用不同的切分策略</strong>。这才是面试官想听你展开的地方。</p><h3 id="策略优先级-结构切分-语义切分-固定长度" tabindex="-1"><a class="header-anchor" href="#策略优先级-结构切分-语义切分-固定长度"><span>策略优先级：结构切分 &gt; 语义切分 &gt; 固定长度</span></a></h3><p><strong>1. 按文档结构切分是最高优先级</strong></p><ul><li>Markdown文档：按H1、H2标题切</li><li>PDF文档：按页切</li><li>代码文件：按函数、类、方法切</li></ul><p>这样做的好处是保留了文档原有的逻辑结构，语义完整性最好。</p><p><strong>2. 语义切分最精准但成本高</strong></p><p>用NLP模型识别句子边界、段落主题，然后按语义相似度切分。效果好，但实现复杂，适合对精度要求极高的场景。</p><p><strong>3. 固定长度是保底方案</strong></p><p>按字符数或token数硬切，优点是简单稳定，缺点是可能破坏语义边界。仅在没有结构信息时使用。</p><h3 id="具体场景的具体策略" tabindex="-1"><a class="header-anchor" href="#具体场景的具体策略"><span>具体场景的具体策略</span></a></h3><table><thead><tr><th>场景</th><th>推荐策略</th><th>关键点</th></tr></thead><tbody><tr><td>企业知识库</td><td>按文档结构切，保留标题层级</td><td>保留文档原有的组织逻辑</td></tr><tr><td>技术文档/代码</td><td>按函数/方法切，chunk size ~100</td><td>代码有强逻辑边界，按自然单元切</td></tr><tr><td>FAQ</td><td>保留完整问答对，不能切</td><td>FAQ的核心是&quot;问-答&quot;完整对应</td></tr><tr><td>结构化数据（表格）</td><td>整表保留，或按行拆</td><td>表格内容不能随意截断</td></tr></tbody></table><p><strong>一个容易踩的坑</strong>：很多人图省事，所有文档都用固定长度切分。这在Demo阶段没问题，但上线后迟早会碰到&quot;检索结果答非所问&quot;的问题。</p><p><strong>更好的做法是Parent-Child Chunk策略</strong>：用小chunk（比如100 tokens）做检索，用大chunk（包含小chunk的父级段落）给LLM提供完整上下文。兼顾检索精度和上下文完整性。</p><figure><img src="/images/rag-interview/20260608_195658_159872_01.png" alt="四象限图，企业知识库/技术文档/FAQ/结构化数据四种场景对应不同切分策略" tabindex="0" loading="lazy"><figcaption>四象限图，企业知识库/技术文档/FAQ/结构化数据四种场景对应不同切分策略</figcaption></figure><hr><h2 id="面试怎么答" tabindex="-1"><a class="header-anchor" href="#面试怎么答"><span>面试怎么答</span></a></h2><h3 id="基础版" tabindex="-1"><a class="header-anchor" href="#基础版"><span>基础版</span></a></h3><blockquote><p>文档切分是RAG系统的地基，直接决定召回精度。chunk size太小会导致语义断裂，召回不完整；太大则语义稀释，embedding失真，通用场景推荐400-512 tokens。overlap用于解决跨chunk的边界丢失问题，推荐10%-20%。不同场景要用不同策略：技术文档按函数切，FAQ保留完整问答对，Markdown按标题层级切。按文档结构切分是最高优先级，而非简单按字符长度切。</p></blockquote><h3 id="加分版" tabindex="-1"><a class="header-anchor" href="#加分版"><span>加分版</span></a></h3><blockquote><p>数据处理管线做到位，比换一百个embedding模型都管用。chunk size的选择要结合具体场景：代码文档建议~100 tokens，通用文本建议400-512 tokens。对于需要保留完整上下文的重要信息，可以采用Parent-Child Chunk策略：小chunk负责检索精度，大chunk负责上下文完整性。overlap比例控制在10%-20%，既能保护边界又不会引入过多冗余。总结一句话：<strong>先按结构切，再按语义调，最后用overlap兜底</strong>。</p></blockquote><figure><img src="/images/rag-interview/20260608_195701_910272_01.png" alt="面试回答要点总结，核心公式：结构切分+chunk大小+overlap=好召回" tabindex="0" loading="lazy"><figcaption>面试回答要点总结，核心公式：结构切分+chunk大小+overlap=好召回</figcaption></figure><hr><h2 id="一句话总结" tabindex="-1"><a class="header-anchor" href="#一句话总结"><span>一句话总结</span></a></h2><p>文档切分是RAG召回质量的天花板：按结构切、用400-512的chunk、加10%-20% overlap，三步搞定。</p>`,55)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};